function Import-MtPackModule {
    <#
    .SYNOPSIS
    Loads a pack that passed the loader gate into its own private module (Maester Packs design, section 4.4).

    .DESCRIPTION
    A pack's helpers, connector files and tests are loaded together into one private module, so its tests
    can call its helpers. Files are dot-sourced by path, never from text, so execution policy and App
    Control apply to them. The module sees Maester's exported commands and nothing private, and exports
    nothing into Maester's scope; the engine calls its functions inside it.

    Before the files load:
    - its Gallery modules are imported into it by the paths Resolve-MtPackSet checked, the modules each one
      requires first, so a RequiredModules entry is met by the pinned version and never by another version
      that happens to be in the store or on PSModulePath. A required module is imported globally, because
      that is where PowerShell looks for it; after each import the modules it was given are checked, and the
      load stops if any is not the pinned copy;
    - the functions that each pack it requires lists in Exports are added to it.

    The module is cached for the session by pack ID and digest, so a run and Connect-Maester share one.
    Throws with the load error.
    #>
    [CmdletBinding()]
    [OutputType([psmoduleinfo])]
    param(
        # A Ready row from Resolve-MtPackSet.
        [Parameter(Mandatory)] [pscustomobject] $Pack,
        # Every row from Resolve-MtPackSet, to find required packs.
        [Parameter()] [object[]] $PackSet = @()
    )

    if (-not $script:__MtPackModules) { $script:__MtPackModules = @{} }
    $key = "$($Pack.Id)|$(if ($Pack.Entry -and $Pack.Entry.Digest) { $Pack.Entry.Digest } else { $Pack.Root })"
    if ($script:__MtPackModules.ContainsKey($key)) { return $script:__MtPackModules[$key].Module }
    if ($Pack.Status -ne 'Ready') { throw "The pack $($Pack.Id) cannot be loaded: $($Pack.Reason)" }

    $m = $Pack.Manifest
    $files = [System.Collections.Generic.List[string]]::new()
    # Helpers are .ps1 files, as the manifest schema says: dot-sourcing a .psm1 would run it as a program.
    foreach ($folder in $m.Helpers) {
        foreach ($f in (Get-ChildItem -LiteralPath (Join-Path $Pack.Root $folder) -Recurse -File -Filter '*.ps1' -ErrorAction Stop | Sort-Object FullName)) { $files.Add($f.FullName) }
    }
    foreach ($c in $m.Connectors) {
        $full = Join-Path $Pack.Root $c.File
        if (-not $files.Contains($full)) { $files.Add($full) }
    }
    foreach ($folder in $m.Suites) {
        foreach ($f in (Get-ChildItem -LiteralPath (Join-Path $Pack.Root $folder) -Recurse -File -Filter 'Test.*.ps1' -ErrorAction Stop | Sort-Object FullName)) { $files.Add($f.FullName) }
    }

    # Modules: the checked store comes first on PSModulePath, once per session, for modules the lock file does not pin.
    $store = (Get-MtPackHome).Modules
    if ($Pack.Modules.Count -gt 0 -and -not (@($env:PSModulePath -split [System.IO.Path]::PathSeparator) -contains $store)) {
        $env:PSModulePath = $store + [System.IO.Path]::PathSeparator + $env:PSModulePath
    }
    # A module the pack runs in a child process is not imported here.
    $declared = @($m.Uses.Modules | Where-Object { -not ($_.PSObject.Properties['Process'] -and $_.Process -eq 'Child') } | ForEach-Object { [string]$_.Name })
    $pinned = @($Pack.Modules)
    # Each module after the pinned modules it requires, so they are loaded from their checked paths first.
    $order = [System.Collections.Generic.List[object]]::new()
    $requiredPaths = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    $visiting = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    $toVersion = { param($v) $parts = @(([string]$v -replace '-.*$', '') -split '\.'); while ($parts.Count -lt 2) { $parts += '0' }; [version]($parts -join '.') }
    $visit = {
        param($row)
        if (($order | Where-Object Path -EQ $row.Path) -or -not $visiting.Add($row.Path)) { return }
        foreach ($r in (Get-MtPackModuleRequirement -Path $row.Path)) {
            $candidates = @($pinned | Where-Object Name -EQ $r.Name)
            # The lowest pinned version it accepts, which is the one the closure pinned for it.
            $dep = if ($r.Version) { $candidates | Where-Object { (& $toVersion $_.Version) -ge (& $toVersion $r.Version) } | Sort-Object { & $toVersion $_.Version } | Select-Object -First 1 }
            if (-not $dep) { $dep = $candidates | Sort-Object { & $toVersion $_.Version } -Descending | Select-Object -First 1 }
            if ($dep) { $null = $requiredPaths.Add($dep.Path); & $visit $dep }
        }
        $order.Add($row)
    }
    foreach ($row in ($pinned | Where-Object { $_.Name -in $declared })) { & $visit $row }
    $moduleList = @($order | ForEach-Object { [pscustomobject]@{ File = (Join-Path $_.Path "$($_.Name).psd1"); Global = $requiredPaths.Contains($_.Path) } })
    $pinnedPaths = @{}
    foreach ($row in $pinned) { $pinnedPaths[$row.Name] = @(@($pinnedPaths[$row.Name]) + [System.IO.Path]::GetFullPath($row.Path).TrimEnd('/', '\') | Where-Object { $_ }) }

    # Exports of required packs.
    $imports = [System.Collections.Generic.List[object]]::new()
    foreach ($r in @($m.RequiredPacks)) {
        $required = $PackSet | Where-Object { $_.Id -eq $r.Id } | Select-Object -First 1
        if (-not $required) { throw "The pack $($Pack.Id) requires $($r.Id), which is not installed." }
        $requiredModule = Import-MtPackModule -Pack $required -PackSet $PackSet
        foreach ($name in $required.Manifest.Exports) {
            $function = & $requiredModule { param($n) Get-Command -Name $n -CommandType Function -ErrorAction SilentlyContinue } $name
            if ($function) { $imports.Add([pscustomobject]@{ Name = $name; ScriptBlock = $function.ScriptBlock }) }
        }
                try { $signature = Get-AuthenticodeSignature -LiteralPath $full -ErrorAction Stop; if ($signature.SignerCertificate) { $signer = $signature.SignerCertificate.GetNameInfo('SimpleName', $false) } } catch { Write-Debug $_ }
            }
            $binaries.Add([pscustomobject]@{ Path = $f.Path; Size = $f.Size; Sha256 = $f.Sha256; Kind = $kind; Signer = $signer })
            & $find 'High' 'Unscannable' "$($f.Path) is $kind that could not be scanned." $f.Path $null
            continue
        }
        if ($extension -in '.ps1', '.psm1', '.psd1', '.json', '.md', '.txt', '.yml', '.yaml', '.xml') {
            $text = [System.IO.File]::ReadAllText($full)
            if ([regex]::IsMatch($text, '[A-Za-z0-9+/]{4096,}={0,2}')) { & $find 'High' 'EncodedContent' "$($f.Path) holds a long encoded block that could not be scanned." $f.Path $null }
        }
    }

    if (-not $manifest) {
        return [pscustomobject]@{ Manifest = $null; Errors = $errors.ToArray(); Warnings = $warnings.ToArray(); Findings = $findings.ToArray(); Risk = 'High'; Binaries = $binaries.ToArray(); Tests = @(); TestIds = @(); Digest = $digest.Digest; Files = $digest.Files }
    }

    # The folders and files the manifest names.
    foreach ($folder in @($manifest.Suites) + @($manifest.Helpers)) {
        if (-not (Test-Path -LiteralPath (Join-Path $root $folder) -PathType Container)) { & $fail 'InvalidManifest' "The folder '$folder' named in maester-pack.json does not exist." }
    }
    foreach ($c in $manifest.Connectors) {
        if ($c.File -and -not (Test-Path -LiteralPath (Join-Path $root $c.File) -PathType Leaf)) { & $fail 'InvalidManifest' "The connector file '$($c.File)' does not exist." }
    }

    # Every PowerShell file: function definitions only; names unique; then the scan.
    $functionFiles = @{}
    $declaredHosts = @($manifest.Uses.Network)
    $declaredModules = @(@($manifest.Uses.Modules) + @($manifest.Uses.UserModules) | ForEach-Object { [string]$_.Name })
    $declaredWrites = @($manifest.Uses.TenantWrites).Count -gt 0
    foreach ($f in ($digest.Files | Where-Object { $_.Path -match '\.ps(m?)1$' })) {
        $scan = Test-MtPackScriptFile -Path (Join-Path $root $f.Path) -DeclaredHost $declaredHosts -DeclaredModule $declaredModules -DeclaredWrites:$declaredWrites
        foreach ($e in $scan.Errors) { & $fail $e.Code "$($f.Path), line $($e.Line): $($e.Message)" }
        foreach ($finding in $scan.Findings) { & $find $finding.Severity $finding.Code $finding.Message $f.Path $finding.Line }
        foreach ($name in $scan.Functions) {
            $key = $name.ToLowerInvariant()
            if ($functionFiles.ContainsKey($key)) { & $fail 'DuplicateFunctionName' "The function $name is defined in both $($functionFiles[$key]) and $($f.Path). Function names must be unique within a pack." }
            else { $functionFiles[$key] = $f.Path }
        }
    }
    foreach ($c in $manifest.Connectors) {
        foreach ($fn in 'Connect', 'Test', 'Disconnect', 'Describe', 'Renew') {
            if ($c.PSObject.Properties[$fn] -and $c.$fn -and -not $functionFiles.ContainsKey(([string]$c.$fn).ToLowerInvariant())) {
                & $fail 'InvalidManifest' "The connector '$($c.Service)' names the function $($c.$fn), which the pack does not define."
            }
        }
    }
    foreach ($name in $manifest.Exports) {
        if (-not $functionFiles.ContainsKey($name.ToLowerInvariant())) { & $fail 'InvalidManifest' "Exports names the function $name, which the pack does not define." }
    }

    # Tests: the 3.0 rules, plus the pack rules.
    $tests = @()
    $packServices = @($manifest.Connectors | ForEach-Object { [string]$_.Service }) + @($RequiredService) + @($manifest.Uses.Services)
    $reservedTags = Get-MtPackReservedTag
    foreach ($folder in $manifest.Suites) {
        $suiteRoot = Join-Path $root $folder
        if (-not (Test-Path -LiteralPath $suiteRoot -PathType Container)) { continue }
        $suiteTests = @(Get-MtNativeTestInventory -Path $suiteRoot -Root $suiteRoot -WarningAction SilentlyContinue)
        foreach ($suiteFile in (Get-ChildItem -LiteralPath $suiteRoot -Recurse -File -Filter 'suite.json' -ErrorAction SilentlyContinue)) {
            try { $suite = Get-Content -LiteralPath $suiteFile.FullName -Raw | ConvertFrom-Json -ErrorAction Stop } catch { & $fail 'InvalidManifest' "$([System.IO.Path]::GetRelativePath($root, $suiteFile.FullName)) is not valid JSON."; continue }
            $relative = [System.IO.Path]::GetRelativePath($root, $suiteFile.FullName)
    param(
        # A report read by Read-MtZtaReport.
        [Parameter(Mandatory)] $Report
    )

    $severity = @{ High = 'High'; Medium = 'Medium'; Low = 'Low' }
    # What each assessment test is about in Maester's terms (product, feature, area, ATT&CK), from the pack's
    # mapping, which build/zta/Update-MtZtaCatalog.ps1 writes into catalog.json.
    $mapped = @{}
    $catalogPath = Join-Path -Path $PSScriptRoot -ChildPath '..' -AdditionalChildPath 'catalog.json'
    if (Test-Path -LiteralPath $catalogPath) {
        foreach ($entry in @((Get-Content -LiteralPath $catalogPath -Raw | ConvertFrom-Json).Tests)) { $mapped[[string]$entry.TestId] = $entry }
    }
    $rows = @($Report.Tests | Where-Object { $_ -and $_.TestStatus -ne 'Planned' -and $_.TestSkipped -ne 'UnderConstruction' })
    $repeated = @($rows | Group-Object -Property { [string]$_.TestId } | Where-Object Count -gt 1 | ForEach-Object Name)
    $seen = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    $sha = [System.Security.Cryptography.SHA256]::Create()
    try {
        foreach ($row in $rows) {
            $id = ([string]$row.TestId -replace '[^A-Za-z0-9._-]', '_') -replace '^[^A-Za-z0-9]+', ''
            if (-not $id) { continue }
            if ([string]$row.TestId -in $repeated) {
                $hash = $sha.ComputeHash([System.Text.Encoding]::UTF8.GetBytes([string]$row.TestTitle))
                $id = '{0}.{1}' -f $id, ([System.Convert]::ToHexString($hash).Substring(0, 10).ToLowerInvariant())
            }
            $unique = $id
            for ($n = 2; -not $seen.Add($unique); $n++) { $unique = "$id.$n" }
            $id = $unique
            $tags = @('ZeroTrust') + @(@($row.TestPillar) | Where-Object { $_ } | ForEach-Object { "ZeroTrust.$_" })
            $instance = [ordered]@{
                Id     = $id
                Title  = ([string]$row.TestTitle -replace '\s+', ' ').Trim()
                Tag    = $tags
                # Shown by the report, which groups the pack's results by pillar and category.
                Fields = [ordered]@{ Pillar = @($row.TestPillar | Where-Object { $_ }); Category = [string]$row.TestCategory }
                Data   = $row
            }
            if ($severity.ContainsKey([string]$row.TestRisk)) { $instance.Severity = $severity[[string]$row.TestRisk] }
            $entry = $mapped[[string]$row.TestId]
            if ($entry) {
                foreach ($name in 'Product', 'RelatedProduct', 'Feature', 'Area', 'UserImpact', 'ImplementationCost', 'Mitre') {
                    $property = $entry.PSObject.Properties[$name]
                    if ($property -and $property.Value) { $instance[$name] = $property.Value }
                }
            }
            [pscustomobject]$instance
        }
    } finally {
        $sha.Dispose()
    }
}

﻿function Get-MtHtmlReport {
    <#
    .Synopsis
    Generates a formatted html report using the MaesterResults object created by ConvertTo-MtMaesterResult

    .Description
    The generated html is a single file that provides a visual representation of the test
    results with a summary view and click through of the details.

    Supports both single-tenant results (from ConvertTo-MtMaesterResult) and multi-tenant
    results (from Merge-MtMaesterResult).

    The report omits each test's ErrorRecord, which the report doesn't display. The
    MaesterResults object passed in and the JSON results file keep it.

    Reports added with Add-MtReportAttachment are embedded in the page, each in its own element, and
    opened from a button. They are left out when RedactUserIdentity is HtmlOnly or AllOutputs, because
    Maester cannot redact another tool's report.

    .Example
    $pesterResults = Invoke-Pester -PassThru
    $maesterResults = ConvertTo-MtMaesterResult $pesterResults
    $output = Get-MtHtmlReport -MaesterResults $maesterResults
    $output | Out-File -FilePath $out.OutputHtmlFile -Encoding UTF8

    This example shows how to generate the html report and save it to a file by using Invoke-Pester

    .Example
    $maesterResults = Invoke-Maester -PassThru
    $output = Get-MtHtmlReport -MaesterResults $maesterResults
    $output | Out-File -FilePath $out.OutputHtmlFile -Encoding UTF8

    This example shows how to generate the html report and save it to a file by using Invoke-Maester

    .Example
    $result1 = Invoke-Maester -PassThru
    $result2 = Invoke-Maester -PassThru
    $merged = Merge-MtMaesterResult -MaesterResults @($result1, $result2)
    $output = Get-MtHtmlReport -MaesterResults $merged
    $output | Out-File -FilePath "MultiTenantReport.html" -Encoding UTF8

    This example shows how to generate a multi-tenant html report

    .LINK
    https://maester.dev/docs/commands/Get-MtHtmlReport
    #>
    [CmdletBinding()]
    param(
        # The Maester test results returned from `Invoke-Pester -PassThru | ConvertTo-MtMaesterResult`
        # or from `Merge-MtMaesterResult` for multi-tenant reports.
        [Parameter(Mandatory = $true, Position = 0, ValueFromPipeline = $true)]
        [psobject] $MaesterResults,

        # Replaces user identities (display names, user principal names and object ids) with stable stable ids.
        # None: keep the values as-is. HtmlOnly / AllOutputs: redact them from this html report.
        [ValidateSet('None', 'HtmlOnly', 'AllOutputs')]
        [string] $RedactUserIdentity = 'None',

        # Replacement map built by Invoke-Maester, which removes the AffectedObjects it was built from.
        [Parameter(DontShow)]
        [hashtable] $UserIdentityReplacementMap
    )

    process {
        # Shallow copy of a results or test object, which may be a PSCustomObject or a hashtable.
        $copyWithout = {
            param($Object, [string] $ExcludeProperty)
            $copy = [ordered]@{}
            if ($Object -is [System.Collections.IDictionary]) {
                foreach ($key in $Object.Keys) {
                    if ($key -ne $ExcludeProperty) { $copy[$key] = $Object[$key] }
                }
            } else {
                foreach ($property in $Object.PSObject.Properties) {
                    if ($property.Name -ne $ExcludeProperty) { $copy[$property.Name] = $property.Value }
                }
            }
            $copy
        }

        # The report doesn't display ErrorRecord, and its stack traces can make up most of the file
        # and include local file paths. Copy the results without it so the caller's object and the
        # JSON output keep the full record.
        $removeErrorRecord = {
            param($Results)
            $copy = & $copyWithout $Results ''
            if ($null -ne $copy.Tests) {
                # Assign directly so a single test or no tests still serializes as an array.
                $copy.Tests = @(foreach ($sourceTest in $copy.Tests) {
                        $test = & $copyWithout $sourceTest 'ErrorRecord'
                        # RelatedObjects only feeds the AffectedObjects built from it, which the report carries.
                        if ($null -ne $test.ResultDetail) {
                            $test.ResultDetail = [PSCustomObject](& $copyWithout $test.ResultDetail 'RelatedObjects')
                        }
                        [PSCustomObject]$test
                    })
            }
            # The Affected objects page only reads these fields, so the report leaves out the rest
            # (UniqueId, UserPrincipalName, AnchorKind and the Sources list). The JSON output and the
            # objects files keep the full records.
            if ($null -ne $copy.AffectedObjects) {
                $copy.AffectedObjects = @($copy.AffectedObjects | ForEach-Object {
                        $slim = [ordered]@{
                            System      = $_.System
                            Type        = $_.Type
                            Id          = $_.Id
                            DisplayName = $_.DisplayName
                            PortalLink  = $_.PortalLink
                            Tests       = @($_.Tests)
                            Referenced  = [bool](@($_.Sources) | Where-Object { $_ -in 'GraphObjects', 'Markdown' })
                        }
                        # Only objects that have facts carry the property, so a report without any stays as small as before.
                        $facts = @(Get-ObjectProperty $_ 'Facts' | Where-Object { $_ })
                        if ($facts.Count -gt 0) {
                            $slim.Facts = @($facts | ForEach-Object {
                                    $fact = [ordered]@{ Name = $_.Name; Value = $_.Value; Tone = $_.Tone; Source = $_.Source; AsOf = $_.AsOf }
                                    # Key and Raw let the report's own summaries read a fact without parsing its text.
                                    $key = Get-ObjectProperty $_ 'Key'
                                    if ($key) { $fact.Key = $key; $fact.Raw = $_.Raw }
                                    [PSCustomObject]$fact
                                })
                        }
                        [PSCustomObject]$slim
                    })
            }
            # The report data lists each attachment without its content, which is written into its own element.
            if ($null -ne $copy.Attachments) {
                if ($RedactUserIdentity -ne 'None') {
                    $copy.Remove('Attachments')
                    $redactedAttachments.Value = $true
                } else {
                    $copy.Attachments = @($copy.Attachments | Where-Object { $_ -and $_.Content } | ForEach-Object {
                            $attachmentContent.Add($_)
                            [PSCustomObject](& $copyWithout $_ 'Content')
                        })
                }
            }
            [PSCustomObject]$copy
        }

        $attachmentContent = [System.Collections.Generic.List[object]]::new()
        $redactedAttachments = [ref]$false
        $reportResults = & $removeErrorRecord $MaesterResults

        # Check the copy rather than the input so hashtable results are detected too.
        # Use depth 7 for multi-tenant to handle: Tenants > Tests > ResultDetail > nested objects
        $isMultiTenant = $reportResults.PSObject.Properties.Name -contains 'Tenants'
        $depth = if ($isMultiTenant) { 7 } else { 5 }
        if ($isMultiTenant -and $null -ne $reportResults.Tenants) {
            $reportResults.Tenants = @($reportResults.Tenants | ForEach-Object { & $removeErrorRecord $_ })
        }

        if ($redactedAttachments.Value) {
            Write-Warning "RedactUserIdentity: the reports added with Add-MtReportAttachment are left out of the HTML report, because they cannot be redacted."
        }

        Write-Verbose "Generating HTML report."
        $json = $reportResults | ConvertTo-Json -Depth $depth -Compress -WarningAction Ignore
        # Redact before escaping: escaped & < > would no longer match the replacement values.
        if ($RedactUserIdentity -ne 'None') {
            if ($PSBoundParameters.ContainsKey('UserIdentityReplacementMap')) {
                $replacements = $UserIdentityReplacementMap
            } else {
                $replacements = Get-MtUserIdentityReplacementMap -MaesterResults $MaesterResults
                $hasInventory = @($MaesterResults) + @($MaesterResults.Tenants) |
                    Where-Object { $_ -and $_.PSObject.Properties.Name -contains 'AffectedObjects' }
                if (-not $hasInventory) {
                    Write-Warning "RedactUserIdentity: the results carry no AffectedObjects, so no user identities can be redacted. Generate them with Invoke-Maester -IncludeAffectedObjects."
                }
            }
            $json = ConvertTo-MtRedactedReportContent -Content $json -ReplacementMap $replacements -JsonEncoded
        }

        # Prevent values from terminating the script element while preserving them when JavaScript parses the JSON.
        $json = $json.Replace('&', '\u0026').Replace('<', '\u003c').Replace('>', '\u003e')

        $htmlFilePath = Join-Path -Path $PSScriptRoot -ChildPath '../../assets/ReportTemplate.html'
        $templateHtml = Get-Content -Path $htmlFilePath -Raw

        # Insert the test results json into the template.
        # Locate the EndOfJson sentinel (handles both double-quote and backtick strings
        # produced by different Vite/Rolldown versions) then walk back to the variable
        # assignment that owns the placeholder object so the same variable name is preserved.
        $endPattern = 'EndOfJson:(?:"EndOfJson"|`EndOfJson`)\}'
        $endMatch = [regex]::Match($templateHtml, $endPattern)
        $insertLocationEnd = $endMatch.Index + $endMatch.Length

        # Find the last variable declaration (var/const/let NAME=) before the end marker.
        $startMatches = [regex]::Matches($templateHtml.Substring(0, $endMatch.Index), '(?:var|const|let)\s+\w+\s*=')
        $startMatch = $startMatches[$startMatches.Count - 1]
        $insertLocationStart = $startMatch.Index + $startMatch.Value.Length  # position just after the '='

        $outputHtml = $templateHtml.Substring(0, $insertLocationStart)
        $outputHtml += $json
        $outputHtml += $templateHtml.Substring($insertLocationEnd)

        # Each attachment is Base64 text, which cannot end the script element. The report reads it by the element's id.
        if ($attachmentContent.Count -gt 0) {
            $elements = foreach ($attachment in $attachmentContent) {
                $id = [string]$attachment.Id -replace '[^A-Za-z0-9_-]', ''
                $content = [string]$attachment.Content -replace '[^A-Za-z0-9+/=]', ''
                '<script type="application/octet-stream" id="maester-attachment-{0}" data-encoding="{1}">{2}</script>' -f $id, 'gzip+base64', $content
            }
            $bodyEnd = $outputHtml.LastIndexOf('</body>', [System.StringComparison]::OrdinalIgnoreCase)
            if ($bodyEnd -lt 0) { $bodyEnd = $outputHtml.Length }
            $outputHtml = $outputHtml.Insert($bodyEnd, ($elements -join "`n") + "`n")
        }

        return $outputHtml
    }
}
